css:
[data-bz-node="ng"][data-bz-node]{padding-top:clamp(56px, 8vw, 100px);padding-bottom:0}
[data-bz-node="ng-grid"][data-bz-node]{grid-template-columns:repeat(auto-fill, minmax(min(100%, 340px), 1fr))}
[data-bz-node="ng-grid"] > [hidden][data-bz-node]{display:none}
/* A post with no picture or no excerpt shows neither, rather than an empty slot. */
[data-bz-node^="ng-img"]:has(.bz-photo--empty),[data-bz-node^="ng-excerpt"]:has(p:empty){display:none}
[data-bz-node^="ng-card"][data-bz-node]{border-style:solid;border-top-color:#c41230;border-right-color:#edebe3;border-bottom-color:#edebe3;border-left-color:#edebe3}
[data-bz-node^="ng-img"][data-bz-node] a{display:block;margin-top:-24px;margin-right:-24px;margin-bottom:0px;margin-left:-24px}
[data-bz-node^="ng-img"][data-bz-node] img{display:block;width:100%;aspect-ratio:16 / 9;object-fit:cover}
[data-bz-node^="ng-img"][data-bz-node] .bz-figure img{border-radius:0}
[data-bz-node^="ng-date"][data-bz-node] p{font-family:Inter, sans-serif;font-size:14px;font-weight:400;font-style:normal;line-height:22.4px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(84, 86, 92);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="ng-title"][data-bz-node] p{font-family:Oswald, sans-serif;font-size:22px;font-weight:600;font-style:normal;line-height:1.2;letter-spacing:0.02em;text-transform:uppercase;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="ng-title"][data-bz-node] a:nth-of-type(1){color:rgb(20, 21, 26);text-decoration:none}
[data-bz-node^="ng-title"][data-bz-node] a:nth-of-type(1):hover{color: rgb(196, 18, 48)}
[data-bz-node^="ng-excerpt"][data-bz-node] p{font-family:Inter, sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:25.6px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(84, 86, 92);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="ng-more"][data-bz-node] p{font-family:Inter, sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:25.6px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin:0}
[data-bz-node^="ng-more"][data-bz-node] a:nth-of-type(1){margin-top:auto;color:rgb(196, 18, 48);font-weight:600;font-size:14px;font-family:Oswald, sans-serif;letter-spacing:0.08em;text-transform:uppercase;text-decoration:none}
[data-bz-node^="ng-more"][data-bz-node] a:nth-of-type(1):hover{color: rgb(143, 13, 33)}
[data-bz-node^="ng-more"]{margin-top:auto}
